import json,pathlib
R=pathlib.Path.cwd()
def read(n):return json.loads((R/n).read_text())
def write(n,v):(R/n).write_text(json.dumps(v,indent=2))
source=read('source-analysis.json');source={k:source[k] for k in ['skill','reasoning_steps','invariants','permitted_variations','source_refs','evidence_paths']}
